+});

diff --git a/apps/web/src/telemetry/stream/query.policy.ts b/apps/web/src/telemetry/stream/query.policy.ts
new file mode 100644
index 0000000..a23f92b
--- /dev/null
+++ b/apps/web/src/telemetry/stream/query.policy.ts
@@ -0,0 +1,230 @@
+/**
+ * The stream's filter grammar (#81): enumerated params, exact-match and
+ * time-window semantics only — no wildcards, regex, or full-text, by
+ * ceiling. Parsing and record matching are pure decisions; reading files is
+ * replay.service.ts's job.
+ */
+
+import type { TelemetryRecord } from "@score/core/telemetry/telemetry.interface";
+import { METRIC_LABELS } from "@score/core/telemetry/telemetry.interface";
+import { isRfc3339 } from "@score/core/telemetry/telemetry.policy";
+
+/** What a subscription can select; `snapshot` and `log` are stream-only kinds. */
+export const STREAM_SIGNALS = ["snapshot", "event", "span", "metric", "log"] as const;
+export type StreamSignal = (typeof STREAM_SIGNALS)[number];
+
+export const SUBJECT_KINDS = ["issue", "pull_request", "session", "branch"] as const;
+export type SubjectKind = (typeof SUBJECT_KINDS)[number];
+
+type Phase = (typeof METRIC_LABELS.phase)[number];
+type Outcome = (typeof METRIC_LABELS.outcome)[number];
+
+/** An absent field matches everything; every present field narrows. */
+export interface StreamQuery {
+  readonly projects?: readonly string[];
+  readonly signals?: readonly StreamSignal[];
+  readonly names?: readonly string[];
+  readonly phases?: readonly Phase[];
+  readonly outcomes?: readonly Outcome[];
+  readonly traceId?: string;
+  readonly subject?: { readonly kind: SubjectKind; readonly id: string };
+  readonly sinceMs?: number;
+  readonly untilMs?: number;
+  readonly follow: boolean;
+}
+
+export type QueryParseResult =
+  | { readonly ok: true; readonly query: StreamQuery }
+  | { readonly ok: false; readonly reason: "FILTER_UNKNOWN" | "FILTER_INVALID" };
+
+const KNOWN_PARAMS: ReadonlySet<string> = new Set([
+  "projects",
+  "signals",
+  "names",
+  "phases",
+  "outcomes",
+  "trace_id",
+  "subject_kind",
+  "subject_id",
+  "since",
+  "until",
+  "follow",
+]);
+
+const INVALID: QueryParseResult = { ok: false, reason: "FILTER_INVALID" };
+
+export function parseStreamQuery(params: URLSearchParams): QueryParseResult {
+  for (const key of params.keys()) {
+    if (!KNOWN_PARAMS.has(key)) return { ok: false, reason: "FILTER_UNKNOWN" };
+  }
+  // Comma-separated and repeated params both accumulate; an empty item
+  // (`projects=`) names nothing exactly, so it is invalid rather than a
+  // silent match-all.
+  const list = (name: string): readonly string[] | undefined => {
+    const values = params.getAll(name).flatMap((value) => value.split(","));
+    return values.length === 0 ? undefined : values;
+  };
+  const enums = <T extends string>(
+    name: string,
+    allowed: readonly T[],
+  ): readonly T[] | undefined | "INVALID" => {
+    const values = list(name);
+    if (values === undefined) return undefined;
+    return values.every((value): value is T => (allowed as readonly string[]).includes(value))
+      ? (values as readonly T[])
+      : "INVALID";
+  };
+  const time = (name: string): number | undefined | "INVALID" => {
+    const value = params.get(name);
+    if (value === null) return undefined;
+    // The record-timestamp bar (#74): shape and calendar ranges both —
+    // Date.parse alone would normalize 2026-02-30 into March.
+    if (!isRfc3339(value)) return "INVALID";
+    const ms = Date.parse(value);
+    return Number.isNaN(ms) ? "INVALID" : ms;
+  };
+
+  const projects = list("projects");
+  const names = list("names");
+  if (projects?.includes("") || names?.includes("")) return INVALID;
+  const signals = enums("signals", STREAM_SIGNALS);
+  const phases = enums("phases", METRIC_LABELS.phase);
+  const outcomes = enums("outcomes", METRIC_LABELS.outcome);
+  if (signals === "INVALID" || phases === "INVALID" || outcomes === "INVALID") return INVALID;
+  const traceId = params.get("trace_id") ?? undefined;
+  if (traceId === "") return INVALID;
+
+  const subjectKind = params.get("subject_kind");
+  const subjectId = params.get("subject_id");
+  // The pair addresses one subject; half a pair narrows to nothing knowable.
+  if ((subjectKind === null) !== (subjectId === null)) return INVALID;
+  let subject: StreamQuery["subject"];
+  if (subjectKind !== null && subjectId !== null) {
+    if (!(SUBJECT_KINDS as readonly string[]).includes(subjectKind) || subjectId === "") {
+      return INVALID;
+    }
+    subject = { kind: subjectKind as SubjectKind, id: subjectId };
+  }
+
+  const sinceMs = time("since");
+  const untilMs = time("until");
+  if (sinceMs === "INVALID" || untilMs === "INVALID") return INVALID;
+
+  const follow = params.get("follow");
+  if (follow !== null && follow !== "true" && follow !== "false") return INVALID;
+
+  return {
+    ok: true,
+    query: {
+      ...(projects && { projects }),
+      ...(signals && { signals }),
+      ...(names && { names }),
+      ...(phases && { phases }),
+      ...(outcomes && { outcomes }),
+      ...(traceId !== undefined && { traceId }),
+      ...(subject && { subject }),
+      ...(sinceMs !== undefined && { sinceMs }),
+      ...(untilMs !== undefined && { untilMs }),
+      // The epic's default is a stream that stays open; this PR closes it at
+      // the seam either way, but the default still selects the warning path.
+      follow: follow !== "false",
+    },
+  };
+}
+
+export function wantsSignal(query: StreamQuery, signal: StreamSignal): boolean {
+  return query.signals === undefined || query.signals.includes(signal);
+}
+
+/** A parsed dated-log line; the prose text is the whole payload. */
+export interface StreamLogRecord {
+  readonly project: string;
+  readonly ts: string;
+  readonly level: string;
+  readonly body: string;
+}
+
+export function matchesTelemetry(query: StreamQuery, record: TelemetryRecord): boolean {
+  if (!wantsSignal(query, record.signal)) return false;
+  if (query.names !== undefined && !query.names.includes(record.name)) return false;
+  if (query.phases !== undefined) {
+    const phase = phaseOf(record);
+    if (phase === undefined || !query.phases.includes(phase)) return false;
+  }
+  if (query.outcomes !== undefined) {
+    const outcome = outcomeOf(record);
+    if (outcome === undefined || !query.outcomes.includes(outcome)) return false;
+  }
+  if (query.traceId !== undefined && record.attributes?.trace_id !== query.traceId) return false;
+  if (query.subject !== undefined && !subjectMatches(query.subject, record.subject)) return false;
+  return inWindow(query, record.ts);
+}
+
+/**
+ * Prose lines carry no name, phase, outcome, trace, or subject — a filter on
+ * any of those excludes the log source entirely rather than guessing from
+ * free text (the no-full-text ceiling).
+ */
+export function matchesLog(query: StreamQuery, record: StreamLogRecord): boolean {
+  if (!wantsSignal(query, "log")) return false;
+  if (
+    query.names !== undefined ||
+    query.phases !== undefined ||
+    query.outcomes !== undefined ||
+    query.traceId !== undefined ||
+    query.subject !== undefined
+  ) {
+    return false;
+  }
+  return inWindow(query, record.ts);
+}
+
+function inWindow(query: StreamQuery, ts: string): boolean {
+  if (query.sinceMs === undefined && query.untilMs === undefined) return true;
+  const ms = Date.parse(ts);
+  // An unparseable timestamp has no place in any window.
+  if (Number.isNaN(ms)) return false;
+  return (
+    (query.sinceMs === undefined || ms >= query.sinceMs) &&
+    (query.untilMs === undefined || ms <= query.untilMs)
+  );
+}
+
+/** Spans carry `attributes.phase`, metrics `labels.phase`, decision events their name's segment. */
+function phaseOf(record: TelemetryRecord): Phase | undefined {
+  const declared = record.signal === "metric" ? record.labels?.phase : record.attributes?.phase;
+  if (typeof declared === "string" && isPhase(declared)) return declared;
+  const segment = record.name.split(".")[1];
+  return segment !== undefined && isPhase(segment) ? segment : undefined;
+}
+
+function isPhase(value: string): value is Phase {
+  return (METRIC_LABELS.phase as readonly string[]).includes(value);
+}
+
+/** Spans have `status`, metrics `labels.outcome`; events carry no outcome. */
+function outcomeOf(record: TelemetryRecord): Outcome | undefined {
+  if (record.signal === "span") return record.status;
+  if (record.signal === "metric") return record.labels?.outcome;
+  return undefined;
+}
+
+function subjectMatches(
+  filter: NonNullable<StreamQuery["subject"]>,
+  subject: TelemetryRecord["subject"],
+): boolean {
+  if (subject === undefined) return false;
+  switch (filter.kind) {
+    case "issue":
+      return subject.issue_number !== undefined && String(subject.issue_number) === filter.id;
+    case "pull_request":
+      return (
+        subject.pull_request_number !== undefined &&
+        String(subject.pull_request_number) === filter.id
+      );
+    case "session":
+      return subject.session === filter.id;
+    case "branch":
+      return subject.branch === filter.id;
+  }
+}

diff --git a/apps/web/src/telemetry/stream/replay.policy.ts b/apps/web/src/telemetry/stream/replay.policy.ts
new file mode 100644
index 0000000..fe8be0a
--- /dev/null
+++ b/apps/web/src/telemetry/stream/replay.policy.ts
@@ -0,0 +1,122 @@
+/**
+ * Pure replay planning (#81): given the marks captured at subscribe and an
+ * optionally presented cursor, decide where each project/source pair starts,
+ * which cursors expired, and what the composite watermark looks like. All
+ * I/O — capturing the marks and walking the bytes — lives in
+ * replay.service.ts.
+ */
+
+import type { TelemetryCursor, TelemetrySource } from "@score/core/telemetry/telemetry.interface";
+
+export interface SegmentMark {
+  readonly segment: string;
+  /** Byte length at subscribe — the fixed high-water mark. */
+  readonly mark: number;
+}
+
+export interface PairMarks {
+  readonly project: string;
+  readonly source: TelemetrySource;
+  /** Ascending by date; segment names are UTC dates, so lexical order is time order. */
+  readonly segments: readonly SegmentMark[];
+}
+
+/** One project's high-water positions: newest segment + captured mark per source. */
+export function watermarkFor(
+  pairs: readonly PairMarks[],
+  project: string,
+): readonly TelemetryCursor[] {
+  return pairs
+    .filter((pair) => pair.project === project && pair.segments.length > 0)
+    .map((pair) => {
+      const newest = pair.segments[pair.segments.length - 1] as SegmentMark;
+      return {
+        project,
+        source: pair.source,
+        segment: newest.segment,
+        byte_offset: newest.mark,
+      };
+    });
+}
+
+export interface SegmentPlan extends SegmentMark {
+  readonly start: number;
+}
+
+export interface PairPlan {
+  readonly project: string;
+  readonly source: TelemetrySource;
+  readonly segments: readonly SegmentPlan[];
+  /** Absent when the pair has no files and no presented position. */
+  readonly position?: TelemetryCursor;
+}
+
+export type ReplayPlan =
+  | { readonly ok: true; readonly pairs: readonly PairPlan[] }
+  | { readonly ok: false; readonly reason: "CURSOR_EXPIRED" };
+
+/**
+ * Positions each pair from a presented cursor component, or at its first
+ * segment. A component naming a segment that is gone — bytes already
+ * consumed from it, or dated before a retained segment — was deleted by
+ * retention: the whole subscribe expires (410) before any event, never a
+ * silent skip. A component dated after every retained segment consumed them
+ * all; replay for that pair is empty, not expired — the same boundary as
+ * TelemetryLogService.read, where an offset-zero date with no retained
+ * evidence around it is indistinguishable from a date that never had records.
+ */
+export function planReplay(
+  pairs: readonly PairMarks[],
+  cursor: readonly TelemetryCursor[] | undefined,
+): ReplayPlan {
+  const plans: PairPlan[] = [];
+  for (const pair of pairs) {
+    const component = cursor?.find(
+      (candidate) => candidate.project === pair.project && candidate.source === pair.source,
+    );
+    if (component === undefined) {
+      const segments = pair.segments.map((segment) => ({ ...segment, start: 0 }));
+      plans.push({
+        project: pair.project,
+        source: pair.source,
+        segments,
+        ...(segments[0] && {
+          position: {
+            project: pair.project,
+            source: pair.source,
+            segment: segments[0].segment,
+            byte_offset: 0,
+          },
+        }),
+      });
+      continue;
+    }
+    const named = pair.segments.find((segment) => segment.segment === component.segment);
+    if (named === undefined) {
+      if (
+        component.byte_offset > 0 ||
+        pair.segments.some((segment) => segment.segment > component.segment)
+      ) {
+        return { ok: false, reason: "CURSOR_EXPIRED" };
+      }
+      // Every retained segment predates the component: already consumed.
+      plans.push({ project: pair.project, source: pair.source, segments: [], position: component });
+      continue;
+    }
+    const segments = pair.segments
+      .filter((segment) => segment.segment >= component.segment)
+      .map((segment) => ({
+        ...segment,
+        start: segment.segment === component.segment ? component.byte_offset : 0,
+      }));
+    plans.push({ project: pair.project, source: pair.source, segments, position: component });
+  }
+  return { ok: true, pairs: plans };
+}
+
+/** The composite cursor before any record: every positioned pair at its start. */
+export function initialCursor(pairs: readonly PairPlan[]): readonly TelemetryCursor[] {
+  return pairs
+    .map((pair) => pair.position)
+    .filter((position): position is TelemetryCursor => position !== undefined);
+}

diff --git a/apps/web/src/telemetry/stream/replay.service.test.ts b/apps/web/src/telemetry/stream/replay.service.test.ts
new file mode 100644
index 0000000..63c2b3b
--- /dev/null
+++ b/apps/web/src/telemetry/stream/replay.service.test.ts
@@ -0,0 +1,281 @@
+import { appendFileSync, rmSync, statSync } from "node:fs";
+import { join } from "node:path";
+import type { TelemetryCursor } from "@score/core/telemetry/telemetry.interface";
+import { afterEach, expect, test } from "vitest";
+import { cleanupSandboxes, newProjectsDir, seed, seedRecords } from "./fixtures/stream.fixture";
+import type { StreamQuery } from "./query.policy";
+import { initialCursor, planReplay, watermarkFor } from "./replay.policy";
+import type { ReplayEmission } from "./replay.service";
+import { REPLAY_BATCH_LIMIT, ReplayService, readCycle } from "./replay.service";
+
+afterEach(cleanupSandboxes);
+
+const ALL: StreamQuery = { follow: true };
+
+function event(i: number): object {
+  return {
+    v: 1,
+    ts: "2026-08-15T11:00:00.000Z",
+    project: "score",
+    signal: "event",
+    name: "score.dispatch.decision",
+    attributes: { decision: "started", n: i },
+  };
+}
+
+function run(
+  projectsDir: string,
+  keys: readonly string[],
+  sources: readonly ("telemetry" | "log")[],
+  cursor?: readonly TelemetryCursor[],
+  query: StreamQuery = ALL,
+): readonly ReplayEmission[] {
+  const service = new ReplayService(projectsDir);
+  const plan = planReplay(service.captureMarks(keys, sources), cursor);
+  if (!plan.ok) throw new Error("unexpected CURSOR_EXPIRED");
+  return [...service.replay(plan.pairs, query)];
+}
+
+function records(emissions: readonly ReplayEmission[]): readonly number[] {
+  return emissions.flatMap((emission) =>
+    emission.kind === "telemetry" ? [(emission.record.attributes as { n: number }).n] : [],
+  );
+}
+
+test("batch cap: a mark spanning far more than 500 records arrives complete, in order", () => {
+  const dir = newProjectsDir();
+  const total = REPLAY_BATCH_LIMIT * 2 + 200;
+  seedRecords(
+    dir,
+    "score",
+    "2026-08-15",
+    Array.from({ length: total }, (_, i) => event(i)),
+  );
+  const emissions = run(dir, ["score"], ["telemetry"]);
+  expect(records(emissions)).toEqual(Array.from({ length: total }, (_, i) => i));
+  expect(REPLAY_BATCH_LIMIT).toBe(500);
+});
+
+test("one I/O cycle parses at most REPLAY_BATCH_LIMIT records and the next resumes exactly", () => {
+  const dir = newProjectsDir();
+  const total = REPLAY_BATCH_LIMIT + 7;
+  seedRecords(
+    dir,
+    "score",
+    "2026-08-15",
+    Array.from({ length: total }, (_, i) => event(i)),
+  );
+  const path = join(dir, "score", "telemetry", "2026-08-15.jsonl");
+  const mark = statSync(path).size;
+  const first = readCycle(path, 0, mark);
+  if (first === "UNREADABLE") throw new Error("unexpected UNREADABLE");
+  expect(first.lines).toHaveLength(REPLAY_BATCH_LIMIT);
+  const next = readCycle(path, first.lines.at(-1)?.end ?? 0, mark);
+  if (next === "UNREADABLE") throw new Error("unexpected UNREADABLE");
+  expect(next.lines).toHaveLength(7);
+  expect(next.lines.at(-1)?.end).toBe(mark);
+});
+
+test("continuous writes: records appended after subscribe stay beyond the fixed mark", () => {
+  const dir = newProjectsDir();
+  seedRecords(
+    dir,
+    "score",
+    "2026-08-15",
+    Array.from({ length: 600 }, (_, i) => event(i)),
+  );
+  const service = new ReplayService(dir);
+  const plan = planReplay(service.captureMarks(["score"], ["telemetry"]), undefined);
+  if (!plan.ok) throw new Error("unexpected CURSOR_EXPIRED");
+  const path = join(dir, "score", "telemetry", "2026-08-15.jsonl");
+  // Writer keeps appending: before the first read and between batches.
+  appendFileSync(path, `${JSON.stringify(event(9000))}\n`);
+  const generator = service.replay(plan.pairs, ALL);
+  const first = generator.next().value as ReplayEmission;
+  appendFileSync(path, `${JSON.stringify(event(9001))}\n`);
+  const rest = [...generator];
+  expect(records([first, ...rest])).toEqual(Array.from({ length: 600 }, (_, i) => i));
+});
+
+test("the incomplete tail is withheld — even once the writer completes it past the mark", () => {
+  const dir = newProjectsDir();
+  seedRecords(dir, "score", "2026-08-15", [event(0)]);
+  const path = join(dir, "score", "telemetry", "2026-08-15.jsonl");
+  appendFileSync(path, '{"v":1,"torn');
+  const service = new ReplayService(dir);
+  const plan = planReplay(service.captureMarks(["score"], ["telemetry"]), undefined);
+  if (!plan.ok) throw new Error("unexpected CURSOR_EXPIRED");
+  appendFileSync(path, '":true}\n');
+  const emissions = [...service.replay(plan.pairs, ALL)];
+  expect(records(emissions)).toEqual([0]);
+  // The cursor stops at the last complete line, not the mark: the torn
+  // bytes stay ahead of it for #82's resume.
+  const last = emissions.at(-1);
+  expect(last?.cursor).toEqual([
+    {
+      project: "score",
+      source: "telemetry",
+      segment: "2026-08-15",
+      byte_offset: expect.any(Number),
+    },
+  ]);
+});
+
+test("filtered records advance the final cursor to the mark without emitting frames", () => {
+  const dir = newProjectsDir();
+  seedRecords(dir, "score", "2026-08-15", [event(0), event(1)]);
+  const path = join(dir, "score", "telemetry", "2026-08-15.jsonl");
+  const service = new ReplayService(dir);
+  const plan = planReplay(service.captureMarks(["score"], ["telemetry"]), undefined);
+  if (!plan.ok) throw new Error("unexpected CURSOR_EXPIRED");
+  const generator = service.replay(plan.pairs, { follow: true, names: ["score.landing.decision"] });
+  let step = generator.next();
+  while (!step.done) step = generator.next();
+  expect(step.value).toEqual([
+    {
+      project: "score",
+      source: "telemetry",
+      segment: "2026-08-15",
+      byte_offset: statSync(path).size,
+    },
+  ]);
+});
+
+test("an unparseable or unknown-version line warns once per segment and never drops neighbours", () => {
+  const dir = newProjectsDir();
+  seed(
+    dir,
+    "score",
+    "telemetry/2026-08-15.jsonl",
+    `${JSON.stringify(event(0))}\nnot json\n{"v":2,"name":"future"}\n${JSON.stringify(event(1))}\n`,
+  );
+  const emissions = run(dir, ["score"], ["telemetry"]);
+  expect(records(emissions)).toEqual([0, 1]);
+  expect(emissions.filter((emission) => emission.kind === "warning")).toEqual([
+    expect.objectContaining({ reason: "RECORD_UNPARSEABLE" }),
+  ]);
+});
+
+test("a segment deleted after capture warns SEGMENT_UNREADABLE and replay continues", () => {
+  const dir = newProjectsDir();
+  seedRecords(dir, "score", "2026-08-14", [event(0)]);
+  seedRecords(dir, "score", "2026-08-15", [event(1)]);
+  const service = new ReplayService(dir);
+  const plan = planReplay(service.captureMarks(["score"], ["telemetry"]), undefined);
+  if (!plan.ok) throw new Error("unexpected CURSOR_EXPIRED");
+  rmSync(join(dir, "score", "telemetry", "2026-08-14.jsonl"));
+  const emissions = [...service.replay(plan.pairs, ALL)];
+  expect(emissions.map((emission) => emission.kind)).toEqual(["warning", "telemetry"]);
+  expect(records(emissions)).toEqual([1]);
+});
+
+test("a presented cursor resumes after consumed records and skips consumed segments", () => {
+  const dir = newProjectsDir();
+  seedRecords(dir, "score", "2026-08-14", [event(0), event(1)]);
+  seedRecords(dir, "score", "2026-08-15", [event(2), event(3)]);
+  const full = run(dir, ["score"], ["telemetry"]);
+  // Resume from the composite cursor emitted with record 2.
+  const at = full[2];
+  if (at === undefined || at.kind === "warning") throw new Error("expected a record");
+  const resumed = run(dir, ["score"], ["telemetry"], at.cursor);
+  expect(records(resumed)).toEqual([3]);
+});
+
+test("a cursor offset landing mid-line drops the torn fragment and resyncs", () => {
+  const dir = newProjectsDir();
+  seedRecords(dir, "score", "2026-08-15", [event(0), event(1)]);
+  const emissions = run(
+    dir,
+    ["score"],
+    ["telemetry"],
+    [{ project: "score", source: "telemetry", segment: "2026-08-15", byte_offset: 3 }],
+  );
+  expect(records(emissions)).toEqual([1]);
+});
+
+test("cursor naming a deleted segment → CURSOR_EXPIRED before any event", () => {
+  const dir = newProjectsDir();
+  seedRecords(dir, "score", "2026-08-15", [event(0)]);
+  const service = new ReplayService(dir);
+  const marks = service.captureMarks(["score"], ["telemetry"]);
+  // Older than every retained segment: retention removed it.
+  expect(
+    planReplay(marks, [
+      { project: "score", source: "telemetry", segment: "2026-08-10", byte_offset: 0 },
+    ]),
+  ).toEqual({ ok: false, reason: "CURSOR_EXPIRED" });
+  // Consumed bytes from a file that is gone entirely.
+  expect(
+    planReplay(service.captureMarks(["score"], ["log"]), [
+      { project: "score", source: "log", segment: "2026-08-10", byte_offset: 12 },
+    ]),
+  ).toEqual({ ok: false, reason: "CURSOR_EXPIRED" });
+});
+
+test("cursor dated after every retained segment means fully consumed, not expired", () => {
+  const dir = newProjectsDir();
+  seedRecords(dir, "score", "2026-08-15", [event(0)]);
+  const emissions = run(
+    dir,
+    ["score"],
+    ["telemetry"],
+    [{ project: "score", source: "telemetry", segment: "2026-08-16", byte_offset: 0 }],
+  );
+  expect(emissions).toEqual([]);
+});
+
+test("log source: dated prose lines become records; a shapeless line warns", () => {
+  const dir = newProjectsDir();
+  seed(
+    dir,
+    "score",
+    "logs/2026-08-15.log",
+    "[2026-08-15T11:59:00.000Z] [info] tick 7 complete\nno shape here\n[2026-08-15T11:59:05.000Z] [warn] slow pass\n",
+  );
+  const emissions = run(dir, ["score"], ["log"]);
+  expect(
+    emissions.map((emission) => (emission.kind === "log" ? emission.record.level : emission.kind)),
+  ).toEqual(["info", "warning", "warn"]);
+  const first = emissions[0];
+  if (first?.kind !== "log") throw new Error("expected a log record");
+  expect(first.record).toEqual({
+    project: "score",
+    ts: "2026-08-15T11:59:00.000Z",
+    level: "info",
+    body: "tick 7 complete",
+  });
+});
+
+test("filtered-out records emit no frames", () => {
+  const dir = newProjectsDir();
+  seedRecords(dir, "score", "2026-08-15", [event(0), event(1)]);
+  const emissions = run(dir, ["score"], ["telemetry"], undefined, {
+    follow: true,
+    names: ["score.landing.decision"],
+  });
+  expect(emissions).toEqual([]);
+});
+
+test("composite cursor carries every positioned pair; a quiet pair keeps its place", () => {
+  const dir = newProjectsDir();
+  seedRecords(dir, "alpha", "2026-08-15", [event(0)]);
+  seedRecords(dir, "beta", "2026-08-15", [event(1)]);
+  seed(dir, "beta", "logs/2026-08-15.log", "[2026-08-15T11:00:00.000Z] [info] hello\n");
+  const service = new ReplayService(dir);
+  const marks = service.captureMarks(["alpha", "beta"], ["telemetry", "log"]);
+  const plan = planReplay(marks, undefined);
+  if (!plan.ok) throw new Error("unexpected CURSOR_EXPIRED");
+  expect(initialCursor(plan.pairs)).toEqual([
+    { project: "alpha", source: "telemetry", segment: "2026-08-15", byte_offset: 0 },
+    { project: "beta", source: "telemetry", segment: "2026-08-15", byte_offset: 0 },
+    { project: "beta", source: "log", segment: "2026-08-15", byte_offset: 0 },
+  ]);
+  const emissions = [...service.replay(plan.pairs, ALL)];
+  const last = emissions.at(-1);
+  // Every component present on every emission; earlier pairs rest at their marks.
+  expect(last?.cursor.map((component) => component.project)).toEqual(["alpha", "beta", "beta"]);
+  expect(watermarkFor(marks, "beta").map((component) => component.source)).toEqual([
+    "telemetry",
+    "log",
